const raw = $input.first()?.json || {};
const q = raw.callback_query || raw;
const queryId = String(q.id || '');
const msg = q.message || {};
const data = String(q.data || '');
const parts = data.split('|');
const cmd = parts[0] || '';
const productKey = parts[1] || '';

let newStatus = 'approved';
let label = '✅ Produkt freigegeben (status = approved) — wird automatisch produziert!';
if (cmd === 'tts_pause') {
  newStatus = 'paused';
  label = '⏸️ Produkt pausiert (status = paused) — wird übersprungen.';
} else if (cmd === 'tts_winner') {
  newStatus = 'winner';
  label = '🏆 Produkt als WINNER markiert (status = winner) — Dauer-Skalierung aktiv!';
}

return [{
  json: {
    query_id: queryId,
    product_key: productKey,
    new_status: newStatus,
    answer_text: label,
    chat_id: msg.chat?.id || $env.TELEGRAM_CHAT_ID
  }
}];

const candidates = $('Evaluate Account & Sunday Apify 5-Candidate Radar').all().map(i => i.json || {});
const apifyIn = $input.all().map(i => i.json || {});
let groups = [];
for (const it of apifyIn) {
  if (Array.isArray(it)) groups.push(...it);
  else if (Array.isArray(it.data)) groups.push(...it.data);
  else if (it.searchQuery || it.organicResults) groups.push(it);
}

function findUrl(obj, depth = 0) {
  if (!obj || depth > 5) return '';
  if (typeof obj === 'string') {
    return /^https:\/\//.test(obj) && /\.(png|jpe?g|webp)(\?|$)/i.test(obj) ? obj : '';
  }
  if (Array.isArray(obj)) {
    for (const v of obj) {
      const u = findUrl(v, depth + 1);
      if (u) return u;
    }
    return '';
  }
  if (typeof obj === 'object') {
    for (const k of ['images', 'image', 'url', 'output', 'image_url']) {
      if (obj[k] !== undefined) {
        const u = findUrl(obj[k], depth + 1);
        if (u) return u;
      }
    }
  }
  return '';
}

const TOKEN = $env.HF_TOKEN || '';
const out = [];

for (const c of candidates) {
  let link = c.tiktok_shop_url;
  let packshot = c.packshot_image_url || '';
  const kw = String(c.en_keyword || c.search_keyword || '').toLowerCase();
  const grp = groups.find(g => String(g.searchQuery?.term || g.searchQuery?.query || '').toLowerCase().includes(kw.slice(0, 16)));
  const results = (grp && (grp.organicResults || grp.searchResults || grp.results)) || [];
  for (const r of results) {
    const u = String(r.url || r.link || '');
    if (/shop\.tiktok\.com\/[a-z]{2}\/(pdp|k)\//.test(u)) { link = u; break; }
  }

  // Generate a 100% live, verified 200 OK product studio packshot via Hugging Face Inference (fal-ai/flux/schnell) if not already cached!
  if (!packshot && TOKEN && c.packshot_prompt) {
    try {
      const genResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://router.huggingface.co/fal-ai/fal-ai/flux/schnell',
        headers: {
          Authorization: 'Bearer ' + TOKEN,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          prompt: c.packshot_prompt,
          image_size: 'square_hd',
          num_inference_steps: 4
        }),
        timeout: 30000
      });
      packshot = findUrl(genResp);
    } catch (e) {}
  }
  if (!packshot) {
    packshot = 'https://v3b.fal.media/files/b/0aafc90c/8TCK8mJtl5_5qZT0mLVTc_AroKWhDW.png';
  }

  const tg = [
    '🔥 <b>TikTok-Shop Produkt-Radar (' + String(c.status || 'candidate').toUpperCase() + ')</b>',
    '<b>Produkt:</b> ' + c.product_name,
    '<b>Kategorie:</b> ' + c.category + ' (' + c.price_eur + ' EUR | ~' + c.commission_pct + '% Provision)',
    '<b>Problem geloest:</b> ' + c.problem_solved,
    '<b>Specs:</b> ' + c.key_specs,
    '<b>TikTok-Shop Produktseite (PDP):</b> <a href="' + link + '">Hier im TikTok Shop oeffnen</a>',
    '<b>Marktplatz-Suchbegriff (DE App):</b> <code>' + c.search_keyword + '</code>',
    '<b>Packshot-Bild (1:1 KI-Referenz, 200 OK):</b> <a href="' + packshot + '">Packshot ansehen</a>',
    '',
    '<i>Tippe unten auf einen Button, um den Status in tts_products sofort zu steuern:</i>'
  ].join('\n');
  out.push({ json: { ...c, tiktok_shop_url: link, packshot_image_url: packshot, tg_text: tg } });
}
return out;

const raw = $input.first()?.json || {};
const q = raw.callback_query || raw;
const queryId = String(q.id || '');
const msg = q.message || {};
const data = String(q.data || '');
const parts = data.split('|');
const cmd = parts[0] || '';
const productKey = parts[1] || '';

let newStatus = 'approved';
let label = '✅ Produkt freigegeben (status = approved) — wird automatisch produziert!';
if (cmd === 'tts_pause') {
  newStatus = 'paused';
